const input = $input.first().json;
const body = input.body ?? input;
const extracao = body.extracao ?? {};
const avaliacao = body.avaliacao ?? {};
const questionario = body.questionario ?? {};
const contexto = questionario.contexto_pedagogico ?? {};
const perfil = questionario.perfil_emocional ?? {};
const casoCorreto = questionario.caso_correto ?? {};
const casoIncorreto = questionario.caso_incorreto ?? {};
const regeneracao = body.regeneracao ?? {};

const submission_id = String(body.submission_id ?? "").trim();
const correct_answer = String(body.correct_answer ?? "").trim();
const feedback_generation = Number(body.feedback_generation ?? 1);

const enunciado = String(extracao.enunciado ?? "").trim();
const desenvolvimento_aluno = String(extracao.desenvolvimento_aluno ?? "").trim();
const resposta_aluno = String(extracao.resposta_aluno ?? "").trim();
const legibilidade = String(extracao.legibilidade ?? "").trim();
const confianca_extracao = Number(extracao.confianca_extracao ?? 0);
const observacoes_extracao = String(extracao.observacoes ?? "").trim();

// Resultado oficial (correto/incorreto) ja vem calculado pelo backend
// (evaluationService.js). Este node NAO recalcula - so le e usa para
// escolher o prompt certo. Duplicar esse calculo aqui foi o bug original.
const status_avaliacao_oficial = String(avaliacao.status ?? "").trim();
const resposta_correta = Boolean(avaliacao.resposta_correta);
const tipo_prompt = status_avaliacao_oficial === "correta" ? "resposta_correta" : "resposta_incorreta";

const intencao_professor = String(body.intencao_professor ?? "").trim();
const regeneracao_solicitada = Boolean(regeneracao.solicitada);
const regeneracao_instrucao = String(regeneracao.instrucao ?? "").trim();

const questionario_tipo = String(questionario.tipo ?? "").trim();
const momento_conteudo = String(contexto.momento_conteudo ?? "").trim();
const estrategias_usadas_lista = Array.isArray(contexto.estrategias_usadas) ? contexto.estrategias_usadas : [];
const reacao_ao_erro = String(perfil.reacao_ao_erro ?? "").trim();
const relacao_com_matematica = String(perfil.relacao_com_matematica ?? "").trim();
const receptividade_feedback = String(perfil.receptividade_feedback ?? "").trim();
const acerto_esperado = String(casoCorreto.acerto_esperado ?? "").trim();
const desempenho_geral = String(casoIncorreto.desempenho_geral ?? "").trim();
const frequencia_erro = String(casoIncorreto.frequencia_erro ?? "").trim();
const natureza_erro = String(casoIncorreto.natureza_erro ?? "").trim();

// Traducao dos slugs do questionario (docs/novo-fluxo/contratos.md secao 3)
// para frases naturais em portugues, para uso dentro do prompt.
const FRASES = {
  momento_conteudo: {
    recente: "foi trabalhado recentemente",
    ja_trabalhado: "já foi bastante trabalhado anteriormente"
  },
  estrategia: {
    explicacao_direta: "exposição direta (explicação no quadro)",
    resolucao_em_grupo: "resolução de problemas em grupo",
    atividade_pratica: "atividade prática/experimental"
  },
  acerto_esperado: {
    sim_esperado: "era o esperado para este aluno",
    sim_com_dificuldade_usual: "era esperado, embora ele costume ter dificuldade nesse tipo de questão",
    nao_surpresa_positiva: "não era esperado — foi uma surpresa positiva"
  },
  desempenho_geral: {
    abaixo_da_media: "abaixo da média da turma",
    mediano: "na média da turma",
    acima_da_media: "acima da média da turma"
  },
  frequencia_erro: {
    frequente: "é frequente para este aluno",
    as_vezes: "acontece às vezes",
    primeira_vez: "é a primeira vez que acontece"
  },
  natureza_erro: {
    compreensao_conceito: "compreensão do conceito",
    distracao: "distração",
    interpretacao_enunciado: "interpretação do enunciado",
    calculo_execucao: "cálculo/execução"
  },
  reacao_ao_erro: {
    frustracao: "fica frustrado(a)",
    indiferenca: "fica indiferente",
    busca_compreender: "busca entender o que aconteceu",
    ansiedade: "fica ansioso(a)",
    variavel: "reage de forma variável, depende do momento"
  },
  relacao_com_matematica: {
    confianca: "tem confiança em relação à matemática",
    neutra: "tem uma relação neutra com a matemática",
    resistencia: "tem resistência em relação à matemática",
    ansiedade: "demonstra ansiedade em relação à matemática"
  },
  receptividade_feedback: {
    boa: "costuma acolher bem o feedback",
    depende_da_abordagem: "recebe bem o feedback dependendo de como ele é dado",
    tende_a_resistir: "tende a resistir ao feedback"
  }
};

function traduzir(mapa, chave) {
  return (mapa && mapa[chave]) || "não informado";
}

const frase_momento_conteudo = traduzir(FRASES.momento_conteudo, momento_conteudo);
const frase_estrategias = estrategias_usadas_lista.length
  ? estrategias_usadas_lista.map((valor) => traduzir(FRASES.estrategia, valor)).join(", ")
  : "não informado";
const frase_reacao_ao_erro = traduzir(FRASES.reacao_ao_erro, reacao_ao_erro);
const frase_relacao_com_matematica = traduzir(FRASES.relacao_com_matematica, relacao_com_matematica);
const frase_receptividade_feedback = traduzir(FRASES.receptividade_feedback, receptividade_feedback);
const frase_acerto_esperado = traduzir(FRASES.acerto_esperado, acerto_esperado);
const frase_desempenho_geral = traduzir(FRASES.desempenho_geral, desempenho_geral);
const frase_frequencia_erro = traduzir(FRASES.frequencia_erro, frequencia_erro);
const frase_natureza_erro = traduzir(FRASES.natureza_erro, natureza_erro);

const intencao_professor_texto = intencao_professor || "nenhuma";

const bloco_base = [
  "Você é um Sistema Tutor Inteligente para matemática do Ensino Fundamental 1.",
  "",
  "Dados da questão:",
  "- Enunciado: " + enunciado,
  "- Resposta correta esperada: " + correct_answer,
  "- Desenvolvimento do aluno: " + (desenvolvimento_aluno || "não informado"),
  "- Resposta final do aluno: " + (resposta_aluno || "não informada"),
  "- Legibilidade da extração: " + (legibilidade || "não informada"),
  "- Confiança da extração: " + confianca_extracao,
  "- Observações da extração: " + (observacoes_extracao || "nenhuma")
].join("\n");

const bloco_regras = [
  "Regras gerais:",
  "1. Não invente informações.",
  "2. Use linguagem simples, respeitosa e encorajadora, adequada para criança do Ensino Fundamental 1.",
  "3. Escreva diretamente para o aluno.",
  "4. Não use tom excessivamente infantilizado.",
  "5. Adapte o tom ao perfil emocional informado abaixo.",
  "6. O feedback deve ter no máximo 10 linhas.",
  "7. Não use markdown nem listas numeradas no texto do feedback.",
  "8. Retorne APENAS JSON válido, sem markdown, sem crases."
].join("\n");

const contexto_aluno_correta = [
  "Contexto do aluno:",
  "- Este conteúdo " + frase_momento_conteudo + ", ensinado por meio de " + frase_estrategias + ".",
  "- O acerto " + frase_acerto_esperado + ".",
  "- Perfil emocional: esse aluno " + frase_reacao_ao_erro + " quando erra; " + frase_relacao_com_matematica + "; e " + frase_receptividade_feedback + ".",
  "- Informação adicional do professor: " + intencao_professor_texto + "."
].join("\n");

const contexto_aluno_incorreta = [
  "Contexto do aluno:",
  "- Este conteúdo " + frase_momento_conteudo + ", ensinado por meio de " + frase_estrategias + ".",
  "- Desempenho geral em matemática: " + frase_desempenho_geral + ".",
  "- Este tipo de erro " + frase_frequencia_erro + ".",
  "- O erro parece ser de " + frase_natureza_erro + " — trate isso como hipótese pedagógica, não certeza absoluta.",
  "- Perfil emocional: esse aluno " + frase_reacao_ao_erro + " quando erra; " + frase_relacao_com_matematica + "; e " + frase_receptividade_feedback + ".",
  "- Informação adicional do professor: " + intencao_professor_texto + "."
].join("\n");

const prompt_resposta_correta = [
  bloco_base,
  "",
  "A resposta final do aluno está CORRETA. Não revele explicitamente a resposta correta no feedback — ela é só uma referência interna.",
  "",
  contexto_aluno_correta,
  "",
  "Sua tarefa:",
  "- Reconhecer o acerto de forma específica (não apenas \"parabéns\").",
  "- Mencionar o que o aluno demonstrou compreender ou fazer bem.",
  "- Reconhecer o esforço e propor um pequeno desafio para continuar avançando.",
  "",
  bloco_regras,
  "",
  "Formato obrigatório:",
  "{",
  "  \"feedback_aluno\": \"\"",
  "}"
].join("\n");

const prompt_resposta_incorreta = [
  bloco_base,
  "",
  "A resposta final do aluno está INCORRETA. Não revele explicitamente a resposta correta no feedback — ela é só uma referência interna. Não resolva toda a questão pelo aluno.",
  "",
  contexto_aluno_incorreta,
  "",
  "Sua tarefa:",
  "- Reconhecer o esforço/tentativa do aluno.",
  "- Orientar sobre onde o raciocínio pode ter se desviado, sem tom punitivo.",
  "- Encorajar e orientar o próximo passo, sem entregar a resposta.",
  "",
  bloco_regras,
  "",
  "Formato obrigatório:",
  "{",
  "  \"feedback_aluno\": \"\"",
  "}"
].join("\n");

const bloco_regeneracao = regeneracao_solicitada
  ? [
      "",
      "",
      "Esta é uma REGERAÇÃO de um feedback já gerado antes. O professor pediu ajustes específicos:",
      "\"" + (regeneracao_instrucao || "sem instrução específica — apenas gerar uma nova variação") + "\"",
      "",
      "Gere uma nova versão do feedback seguindo essa instrução, mantendo todas as regras acima."
    ].join("\n")
  : "";

const prompt_feedback =
  (status_avaliacao_oficial === "correta" ? prompt_resposta_correta : prompt_resposta_incorreta) +
  bloco_regeneracao;

const entrada_valida = Boolean(
  submission_id &&
  correct_answer &&
  enunciado &&
  resposta_aluno &&
  status_avaliacao_oficial
);

return [
  {
    json: {
      timestamp: new Date().toISOString(),
      submission_id,
      feedback_generation,
      correct_answer,
      enunciado,
      desenvolvimento_aluno,
      resposta_aluno,
      legibilidade,
      confianca_extracao,
      observacoes_extracao,
      status_avaliacao_oficial,
      resposta_correta,
      tipo_prompt,
      questionario_tipo,
      momento_conteudo,
      estrategias_usadas: estrategias_usadas_lista.join(", "),
      reacao_ao_erro,
      relacao_com_matematica,
      receptividade_feedback,
      acerto_esperado,
      desempenho_geral,
      frequencia_erro,
      natureza_erro,
      intencao_professor,
      regeneracao_solicitada,
      regeneracao_instrucao,
      entrada_valida,
      prompt_feedback,
      provedor_ia: "gemini",
      modelo_feedback: "gemini"
    }
  }
];

const original = $('Preparar dados').first().json;
const aiOutput = $input.first().json;

function getText(value) {
  if (!value) return "";

  if (typeof value === "string") {
    return value;
  }

  if (Array.isArray(value)) {
    return value.map(getText).filter(Boolean).join("\n");
  }

  if (typeof value === "object") {
    const priorityKeys = [
      "text",
      "output",
      "response",
      "content",
      "message",
      "result"
    ];

    for (const key of priorityKeys) {
      if (value[key]) {
        const found = getText(value[key]);
        if (found) return found;
      }
    }

    if (value.candidates?.[0]?.content?.parts) {
      return getText(value.candidates[0].content.parts);
    }

    if (value.content?.parts) {
      return getText(value.content.parts);
    }
  }

  return "";
}

function extractJson(raw) {
  if (!raw) return null;

  let cleaned = String(raw)
    .replace(/```json/gi, "")
    .replace(/```/g, "")
    .trim();

  const start = cleaned.indexOf("{");
  const end = cleaned.lastIndexOf("}");

  if (start === -1 || end === -1 || end <= start) {
    return null;
  }

  const jsonText = cleaned.slice(start, end + 1);

  try {
    return JSON.parse(jsonText);
  } catch (error) {
    return null;
  }
}

const raw_ai_response = getText(aiOutput);
const feedback = extractJson(raw_ai_response);

const parse_ok = feedback !== null;

const feedback_aluno = feedback?.feedback_aluno ?? "";

// Unico campo realmente exigido pelo backend. Antes exigia tambem
// feedback_professor, que os prompts atuais nunca retornam - isso fazia
// "ok" ser sempre falso mesmo em geracoes bem-sucedidas.
const ok = parse_ok && Boolean(feedback_aluno);

// Campos legado: usam o que a IA retornar; se ausentes, ficam null em vez
// de texto fabricado (o frontend novo nao exibe esses campos mesmo).
const acertou =
  typeof feedback?.acertou === "boolean" ? feedback.acertou : original.resposta_correta;

const status_avaliacao = feedback?.status_avaliacao ?? original.status_avaliacao_oficial ?? null;
const tipo_erro = feedback?.tipo_erro ?? null;
const resumo_erro = feedback?.resumo_erro ?? null;
const feedback_professor = feedback?.feedback_professor ?? null;
const dica_proxima_acao = feedback?.dica_proxima_acao ?? null;
const confianca_feedback =
  feedback?.confianca_feedback !== undefined ? Number(feedback.confianca_feedback) : null;

const status_n8n = ok ? "feedback_gerado_com_sucesso" : "erro_feedback_ia";

const resposta_backend = {
  ok,
  submission_id: original.submission_id,
  fluxo: "geracao_feedback",
  status_n8n,
  feedback_generation: original.feedback_generation,
  provedor_ia: original.provedor_ia,
  modelo: original.modelo_feedback,
  avaliacao: {
    feedback_aluno,
    acertou,
    status_avaliacao,
    tipo_erro,
    resumo_erro,
    feedback_professor,
    dica_proxima_acao,
    confianca_feedback
  },
  entrada: {
    correct_answer: original.correct_answer,
    enunciado: original.enunciado,
    desenvolvimento_aluno: original.desenvolvimento_aluno,
    resposta_aluno: original.resposta_aluno,
    legibilidade: original.legibilidade,
    confianca_extracao: original.confianca_extracao,
    observacoes_extracao: original.observacoes_extracao
  },
  erro: ok
    ? null
    : {
        parse_ok,
        mensagem: parse_ok
          ? "A IA nao retornou feedback_aluno."
          : "A resposta da IA nao contem JSON valido."
      }
};

return [
  {
    json: {
      ...original,
      parse_ok,
      ok,
      status_n8n,
      modelo: original.modelo_feedback,
      acertou,
      status_avaliacao,
      tipo_erro,
      resumo_erro,
      feedback_aluno,
      feedback_professor,
      dica_proxima_acao,
      confianca_feedback,
      raw_ai_response,
      resposta_backend_json: JSON.stringify(resposta_backend),
      resposta_backend
    }
  }
];
